import struct, sys, io, gzip

# Try to read the binlog as text via the diagnostic log that was generated
with open("build.log", "r", errors="replace") as f:
    content = f.read()

# Find errors
lines = content.split('\n')
error_lines = []
for i, line in enumerate(lines):
    if ' error ' in line.lower() and ('CS' in line or 'NU' in line or 'MSB' in line or 'NETSDK' in line):
        error_lines.append(line.strip())

# Also find "Build FAILED" section
in_summary = False
summary_lines = []
for line in lines:
    if 'Build FAILED' in line:
        in_summary = True
    if in_summary:
        summary_lines.append(line)
    if in_summary and len(summary_lines) > 100:
        break

print("=== ERRORS FOUND ===")
for e in error_lines[:50]:
    print(e)
print("\n=== BUILD SUMMARY ===")
for s in summary_lines[:100]:
    print(s)
EOF
python3 extract_errors.py", "description": "Extract errors from build log", "initial_wait": 60}

